  "fixed_code": "import os\nfrom typing import Any\nfrom flask import Flask, abort, request, send_from_directory, Response\nfrom werkzeug.utils import secure_filename\n\napp = Flask(__name__)\nEXPORT_DIR = os.path.realpath(os.environ.get('EXPORT_DIR', '/srv/exports'))\n\n@app.route(\"/exports/download\")\ndef download_export() -> Response:\n    \"\"\"Download a CSV export file by name. Expects 'name' query parameter.\"\"\"\n    name = secure_filename(request.args.get(\"name\", \"\"))\n    if not name or not name.endswith(\".csv\"):\n        abort(400)\n    return send_from_directory(EXPORT_DIR, name, as_attachment=True)"
